do $$ begin create role anon nologin; create role authenticated nologin; create role service_role nologin bypassrls; create role authenticator login noinherit; exception when duplicate_object then null; end $$; grant anon, authenticated, service_role to authenticator;
create schema auth; create schema extensions; create schema storage;
create extension pgcrypto with schema extensions;
create function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb $$;
create function auth.uid() returns text language sql stable as $$ select auth.jwt()->>'sub' $$;
grant usage on schema auth, extensions, storage, public to anon, authenticated, service_role;
grant execute on all functions in schema auth to anon, authenticated, service_role;
create table storage.buckets(id text primary key, name text, public boolean);
create table storage.objects(id uuid default gen_random_uuid() primary key, bucket_id text, name text);
alter table storage.objects enable row level security;
create function storage.foldername(name text) returns text[] language sql immutable as $$ select (string_to_array(name,'/'))[1:array_length(string_to_array(name,'/'),1)-1] $$;
grant all on storage.objects to authenticated, anon, service_role;
-- public tables (mirrors live columns, 2026-10-12)
create table residents(id text primary key, name text, role text, phase integer, house text, updated_at timestamptz, move_in_date date, sobriety_date date, discharge_date date, discharge_reason text, status text, phone text, email text, emergency_name text, emergency_phone text, emergency_relation text, medical_notes text, notify_opt_in boolean, org text, pin_hash text, doc_signer_name text, doc_signer_title text, discharge_sig text, discharge_signed_by text);
create table checkins(id text primary key, resident_id text, resident_name text, meeting_type text, meeting_name text, address text, lat text, lng text, signer_name text, sig_data_url text, ts timestamptz default now(), house text, meeting_lat text, meeting_lng text, distance_from_meeting text, server_ts timestamptz default now(), org text, duration_minutes integer, sig_lat text, sig_lng text, is_online boolean, topic_description text, verified_by_id text, verified_by_name text, verification_note text, verified_at timestamptz);
create table curfew_log(id text primary key, resident_id text, resident_name text, action text, ts timestamptz default now(), lat text, lng text, excused boolean, excused_reason text, late boolean, destination text, house text, server_ts timestamptz default now(), org text);
create table chores(id text primary key, resident_id text, resident_name text, title text, completed boolean, completed_at timestamptz, week_start date, created_at timestamptz default now(), house text, completed_date date, org text);
create table drug_tests(id text primary key, resident_id text, resident_name text, test_date date, test_time text, test_types text, result text, notes text, administered_by text, house text, created_at timestamptz default now(), admin_sig text, resident_sig text, server_ts timestamptz default now(), lab_sent_date date, lab_result text, lab_result_date date, lab_name text, lab_notes text, lab_specimen_id text, lab_sealed boolean, org text);
create table incidents(id text primary key, incident_type text, incident_date text, incident_time text, description text, action_taken text, authorities_notified boolean, resident_id text, resident_name text, reported_by text, house text, created_at timestamptz default now(), org text, contact_notified boolean, contact_notified_note text, incident_sig text);
create table grievances(id text primary key, filed_by text, category text, description text, status text, grievance_date date, house text, resolution text, resolved_by text, resolved_at timestamptz, created_at timestamptz default now(), resident_id text, org text);
create table resident_documents(id text primary key, template_id text, resident_id text, resident_name text, house text, sent_at timestamptz, resident_sig text, resident_signed_at timestamptz, manager_sig text, manager_name text, manager_signed_at timestamptz, status text, created_at timestamptz default now(), template_name text, template_desc text, template_url text, org text, template_file_path text, manager_title text, signed_file_path text);
create table document_templates(id text primary key, name text, description text, file_path text, required_for_onboarding boolean, created_by text, house text, is_global boolean, created_at timestamptz default now(), url text, required boolean, org text);
create table events(id text primary key, title text, event_date date, event_time text, notes text, created_by text, created_at timestamptz default now(), house text, org text);
create table announcements(id text primary key, message text, created_by text, created_at timestamptz default now(), house text, is_global boolean, archived boolean, org text);
create table announcement_acks(id text primary key, announcement_id text, resident_id text, resident_name text, acked_at timestamptz, org text);
create table settings(id serial primary key, required integer, house_name text, manager_name text, lab_policy text, house_coords jsonb, org text unique, feature_curfew boolean, feature_chores boolean, unit_label text, meeting_only boolean, feature_meds boolean, feature_screenings boolean, feature_incidents boolean, feature_documents boolean, feature_events boolean, feature_announcements boolean);
create table timesheets(id text primary key, employee_name text);
create table orgs(id uuid default gen_random_uuid(), subdomain text unique, name text, logo_url text, accent_color text, created_at timestamptz default now());
grant all on all tables in schema public to anon, authenticated, service_role;
grant all on all sequences in schema public to anon, authenticated, service_role;
do $$ declare t text; begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy anon_all_timesheets on timesheets for all to anon using (true);
